def ident(p):
    s=Path(p).lstat()
    return [s.st_dev,s.st_ino,s.st_mode,s.st_size,s.st_mtime_ns,s.st_ctime_ns,s.st_nlink]

def pin(p,sha=None):
    p=Path(p);before=ident(p);assert stat.S_ISREG(before[2])
    h=hashlib.sha256()
    with p.open('rb') as f:
        s=os.fstat(f.fileno());assert [s.st_dev,s.st_ino]==before[:2]
        while b:=f.read(4*1024**2):h.update(b)
    assert ident(p)==before
    rec=dict(path=str(p),identity=before,bytes=before[3],sha256=h.hexdigest())
    if sha:assert rec['sha256']==sha,str(p)
    PINS[str(p)]=rec
    return rec

def metadata(p,sha=None):
    rec=pin(p,sha);b=Path(p).read_bytes()
    assert hashlib.sha256(b).hexdigest()==rec['sha256'] and ident(p)==rec['identity']
    return json.loads(b)

def source(p,sha):
    rec=pin(p,sha);text=Path(p).read_text();assert hashlib.sha256(text.encode()).hexdigest()==rec['sha256']
    return text,ast.parse(text)

def fn(text,tree,name):
    n=next(x for x in tree.body if isinstance(x,ast.FunctionDef) and x.name==name)
    seg=ast.get_source_segment(text,n)
    return dict(name=name,start_line=n.lineno,end_line=n.end_lineno,source_sha256=hashlib.sha256(seg.encode()).hexdigest(),source=seg)

